 ТЕМА: Обчислення в хімії. Обчислення за хімічними рівняннями.
 Завдання скеровано на перевірку вміння розв’язувати комбіновані задачі.
 Дано: 
 m(\mathrm{C_4H_9COOH})=44\ \text{г} 
 m(\mathrm{C_2H_5OH})=25\ \text{г} 
 M(\mathrm{C_4H_9COOH})=88\ \text{г/моль} 
 M(\mathrm{C_2H_5OH})=46\ \text{г/моль} 
 M(\mathrm{C_4H_9COOC_2H_5})=116\ \text{г/моль} 
 \mathbf{\eta}(\mathrm{C_4H_9COOC_2H_5})=0,5 
 Знайти: 
 m_\text{практ.}(\mathrm{C_4H_9COOC_2H_5})\ -\ ? 
 Розв’язання 
 \begin{gather*}
 \mathrm{C_4H_9COOH+C_2H_5OH\rightarrow C_4H_9COOC_2H_5+H_2O}\\[7pt]
 n(\mathrm{C_4H_9COOH})=m(\mathrm{C_4H_9COOH}):M(\mathrm{C_4H_9COOH})\\[7pt]
 n(\mathrm{C_4H_9COOH})=44\ \text{г}:88\ \text{г/моль}=0,5\ \text{моль}\\[7pt]
 n(\mathrm{C_2H_5OH})=m(\mathrm{C_2H_5OH}):M(\mathrm{C_2H_5OH})\\[7pt]
 n(\mathrm{C_2H_5OH})=25\ \text{г}:46\ \text{г/моль}\gt 0,5\ \text{моль} - \text{у надлишку}\\[7pt]
 n(\mathrm{C_4H_9COOC_2H_5})=m(\mathrm{C_4H_9COOH})=0,5\ \text{моль}\\[7pt]
 m_\text{теор.}(\mathrm{C_4H_9COOC_2H_5})n(\mathrm{C_4H_9COOC_2H_5})M(\mathrm{C_4H_9COOC_2H_5})\\[7pt]
 m_\text{практ.}(\mathrm{C_4H_9COOC_2H_5})=n(\mathrm{C_4H_9COOC_2H_5})M(\mathrm{C_4H_9COOC_2H_5})\mathbf{\eta}(\mathrm{C_4H_9COOC_2H_5})\\[7pt]
 m_\text{практ.}(\mathrm{C_4H_9COOC_2H_5})=0,5\ \text{моль}\cdot 116\ \text{г/моль}\cdot 0,5=29\ \text{г}
